//! Port of `terminal/clip/clipclean` (Python): detect text copied from a TUI (lines right-padded to one
//! column width, soft wraps baked in) and rejoin it. No dependencies. Lengths count chars like Python `len`.
//! Parity with the Python version: `tests/golden.rs` against `tests/golden.json` (generated by `clip/gen_golden.py`).

fn len(s: &str) -> usize {
    s.chars().count()
}

fn is_space(c: char) -> bool {
    c.is_whitespace() || ('\x1c'..='\x1f').contains(&c)
}

fn rstrip(s: &str) -> &str {
    s.trim_end_matches(is_space)
}

fn lstrip(s: &str) -> &str {
    s.trim_start_matches(is_space)
}

fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// Python `detect_tui_paste`: (is_tui, padded_width).
pub fn detect(text: &str) -> (bool, usize) {
    let lines: Vec<&str> = text.split('\n').collect();
    if lines.len() < 2 {
        return (false, 0);
    }
    let non_empty: Vec<&str> = lines.iter().copied().filter(|l| !l.is_empty()).collect();
    if non_empty.len() < 2 {
        return (false, 0);
    }
    let lengths: Vec<usize> = non_empty.iter().map(|l| len(l)).collect();
    let padded = non_empty.iter().filter(|l| rstrip(l).len() != l.len()).count();
    let mut counts: Vec<(usize, usize)> = Vec::new();
    for &n in &lengths {
        match counts.iter_mut().find(|(w, _)| *w == n) {
            Some(entry) => entry.1 += 1,
            None => counts.push((n, 1)),
        }
    }
    let (width, count) = counts.iter().fold((0, 0), |best, &(w, c)| if c > best.1 { (w, c) } else { best });
    let total = lengths.len() as f64;
    if count as f64 / total > 0.5 && width > 20 && padded >= 2 && padded as f64 / total >= 0.5 {
        return (true, width);
    }
    if non_empty.len() == 2 {
        let (first, second) = (non_empty[0], non_empty[1]);
        let first_len = len(first);
        let trailing = first_len - len(rstrip(first));
        let shared_margin = non_empty.iter().all(|l| len(l) > len(lstrip(l)));
        if first_len > 20
            && trailing > 0
            && len(rstrip(first)) as f64 >= first_len as f64 * 0.8
            && len(second) <= first_len
            && (trailing >= 3 || shared_margin)
        {
            return (true, first_len);
        }
    }
    (false, width)
}

fn indent(l: &str) -> usize {
    len(l) - len(lstrip(l))
}

fn margin(lines: &[String]) -> usize {
    let indents: Vec<usize> = lines.iter().filter(|l| !strip(l).is_empty()).map(|l| indent(l)).collect();
    let Some(&min_pos) = indents.iter().filter(|&&i| i > 0).min() else { return 0 };
    let has = indents.iter().filter(|&&i| i >= min_pos).count();
    if has as f64 / indents.len() as f64 > 0.5 {
        min_pos
    } else {
        0
    }
}

fn structure_start(s: &str) -> bool {
    let mut c = s.chars();
    let first = c.next();
    let second = c.next();
    let spaced = |x: Option<char>| x.is_some_and(is_space);
    if matches!(first, Some('-' | '*' | '•')) && spaced(second) {
        return true;
    }
    let digits = s.chars().take_while(|&c| is_decimal(c)).count();
    if digits > 0 {
        let mut rest = s.chars().skip(digits);
        if rest.next() == Some('.') && spaced(rest.next()) {
            return true;
        }
    }
    let hashes = s.chars().take_while(|&c| c == '#').count();
    if (1..=6).contains(&hashes) && spaced(s.chars().nth(hashes)) {
        return true;
    }
    matches!(first, Some('>' | '│' | '┃' | '|'))
}

/// Unicode Nd (Python `\\d`): ASCII plus the common decimal blocks.
fn is_decimal(c: char) -> bool {
    if c.is_ascii_digit() {
        return true;
    }
    const ZEROS: &[u32] = &[
        0x660, 0x6F0, 0x7C0, 0x966, 0x9E6, 0xA66, 0xAE6, 0xB66, 0xBE6, 0xC66, 0xCE6, 0xD66, 0xDE6, 0xE50, 0xED0, 0xF20,
        0x1040, 0x1090, 0x17E0, 0x1810, 0x1946, 0x19D0, 0x1A80, 0x1A90, 0x1B50, 0x1BB0, 0x1C40, 0x1C50, 0xA620, 0xA8D0,
        0xA900, 0xA9D0, 0xA9F0, 0xAA50, 0xABF0, 0xFF10,
    ];
    let v = c as u32;
    ZEROS.iter().any(|&z| (z..z + 10).contains(&v))
}

/// Python `clean_tui_paste`: strip padding and margin, rejoin soft-wrapped lines, keep structure and code fences.
pub fn clean(text: &str, padded_width: usize) -> String {
    let mut lines: Vec<String> = text.split('\n').map(|l| rstrip(l).to_string()).collect();
    let m = margin(&lines);
    if m > 0 {
        for l in lines.iter_mut() {
            if !l.is_empty() && indent(l) >= m {
                *l = l.chars().skip(m).collect();
            }
        }
    }
    let content_width = if padded_width > 0 { padded_width as i64 - m as i64 } else { 0 };
    let fence = |l: &str| strip(l).starts_with("```");
    let mut result: Vec<String> = Vec::new();
    let mut in_code = false;
    let mut i = 0;
    while i < lines.len() {
        let line = &lines[i];
        if fence(line) {
            in_code = !in_code;
            result.push(line.clone());
            i += 1;
            continue;
        }
        if in_code {
            result.push(line.clone());
            i += 1;
            continue;
        }
        if strip(line).is_empty() {
            result.push(String::new());
            i += 1;
            continue;
        }
        let mut parts: Vec<String> = vec![line.clone()];
        i += 1;
        while i < lines.len() {
            let next = &lines[i];
            if strip(next).is_empty() || fence(next) || structure_start(next) {
                break;
            }
            let prev = parts.last().unwrap();
            if content_width != 0 && (len(prev) as f64) < content_width as f64 * 0.8 {
                break;
            }
            parts.push(strip(next).to_string());
            i += 1;
        }
        result.push(parts.join(" "));
    }
    let mut joined = result.join("\n");
    while joined.contains("\n\n\n") {
        joined = joined.replace("\n\n\n", "\n\n");
    }
    strip(&joined).to_string()
}

/// Python `cleaned`: Some(clean text) for a TUI copy, None for normal text.
pub fn cleaned(text: &str) -> Option<String> {
    let (tui, width) = detect(text);
    tui.then(|| clean(text, width))
}
